-- Any @yu.edu.sa email becomes a student; staff are promoted by staff_emails below.

-- Majors

-- Clubs

-- Restaurants and menus

-- Shuttle: one route per direction, departures Sunday to Thursday
-- Golf carts (live GPS can be written to vehicle_locations later)

-- Parking: one paid zone with 50 slots (32 currently occupied by other cars) + 4 free sensor zones
select (select id from public.parking_lots where slug = 'paid'), 'P-' || n, (n <= 16 or n >= 35) from generate_series(1, 50) n;

-- Events (dates are relative to the day you run this seed)

-- Instructors (the @yu.edu.sa address is what links a sign-up to the instructor row)
-- Office hours (Dr. Sarah has three windows, everyone else one)
-- Weekly timetables (Sunday to Thursday)

-- Student Affairs services (minutes_per_ticket drives the wait estimate)

-- Display order (same as the prototype)
update public.restaurants set sort_order = array_position(array['kafton','archi','tropika','soon'], slug) - 1;
update public.clubs set sort_order = array_position(array['gdg','sports','photo','debate','robotics','cyber','ai','entre','finance','law','arch','ie','media','arts','music','reading','volunteer','health','chess','esports','toast','env','culture'], slug) - 1;
update public.instructors set sort_order = array_position(array['sarah','faisal','lama','yousef','noura','khalid','omar','reem','majed','hala','tariq','abdullah','maha','fahad','nouf'], slug) - 1;

