  ('west', 'West Parking', 'المواقف الغربية', 'Engineering & Architecture', 'كلية الهندسة والعمارة', 'free', 80, 3, 'Usually full by 8:40 AM', 'تمتلئ عادةً بحلول 8:40 ص', 2),
  ('east', 'East Parking', 'المواقف الشرقية', 'Main Building & Mosque', 'المبنى الرئيسي والمسجد', 'free', 60, 0, 'Full since 8:25 AM · frees up ~12:00 PM', 'ممتلئة منذ 8:25 ص · تتوفر ~12:00 م', 3),
  ('south', 'South Parking', 'المواقف الجنوبية', 'Amin Al-Shibi St · YUPadel', 'شارع أمين الشيبي · YUPadel', 'free', 100, 8, 'Best arrival: before 9:30 AM', 'أفضل وقت للوصول: قبل 9:30 ص', 4);
insert into public.events (slug, club_id, title_en, title_ar, about_en, about_ar, venue_en, venue_ar, venue_detail_en, venue_detail_ar, host_en, host_ar, host_initial, starts_at, ends_at, capacity, registration_url, is_draft, date_set) values
  ('devfest', (select id from public.clubs where slug = 'gdg'), 'GDG DevFest Kickoff', 'انطلاقة GDG DevFest', 'Kick off DevFest season with talks on Android, web and AI from Google Developer Experts, a hands-on Gemini workshop, and networking with the GDG community. Snacks provided.', 'انطلق معنا في موسم DevFest مع محاضرات عن Android والويب والذكاء الاصطناعي من خبراء Google، وورشة عملية على Gemini، وفرصة للتواصل مع مجتمع GDG. تتوفر وجبات خفيفة.', 'Innovation Hub', 'مركز الابتكار', 'Innovation Hub · Building A, Floor 2', 'مركز الابتكار · مبنى A، الدور 2', null, null, 'G', ((now() at time zone 'Asia/Riyadh')::date + 8 + time '18:30') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 8 + time '21:00') at time zone 'Asia/Riyadh', 120, 'https://gdg.community.dev', false, true),
  ('career-fair', null, 'Career Fair 2026', 'معرض التوظيف 2026', 'Meet 40+ employers from banking, tech, energy and government. Bring your CV — on-the-spot interviews for final-year students.', 'التقِ بأكثر من 40 جهة توظيف من البنوك والتقنية والطاقة والقطاع الحكومي. أحضر سيرتك الذاتية — مقابلات فورية لطلاب السنة الأخيرة.', 'Main Hall', 'القاعة الرئيسية', 'Main Hall · Main Building', 'القاعة الرئيسية · المبنى الرئيسي', 'Student Affairs', 'شؤون الطلاب', 'Y', ((now() at time zone 'Asia/Riyadh')::date + 12 + time '10:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 12 + time '15:00') at time zone 'Asia/Riyadh', 600, null, false, true),
  ('national-day', null, 'Saudi National Day Celebration', 'احتفال اليوم الوطني السعودي', 'Celebrate with traditional performances, Saudi food stalls, a photo booth and fireworks to close the night.', 'احتفل معنا بالعروض الشعبية وأركان الأكلات السعودية وركن التصوير، وتختتم الليلة بالألعاب النارية.', 'Main Courtyard', 'الساحة الرئيسية', 'Main Courtyard · Main Building', 'الساحة الرئيسية · المبنى الرئيسي', 'Student Affairs', 'شؤون الطلاب', 'Y', ((now() at time zone 'Asia/Riyadh')::date + 0 + time '19:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 0 + time '22:00') at time zone 'Asia/Riyadh', 800, null, false, true),
  ('photo-meetup', (select id from public.clubs where slug = 'photo'), 'Photography Club Meetup', 'لقاء نادي التصوير', 'Weekly meetup: this week is golden-hour portraits around campus. Bring any camera — phones welcome.', 'اللقاء الأسبوعي: تصوير البورتريه وقت الغروب في أرجاء الجامعة. أحضر أي كاميرا — الجوال مرحب به.', 'Art Studio', 'مرسم الفنون', 'Art Studio · Tuwaiq Building', 'مرسم الفنون · مبنى طويق', null, null, 'P', ((now() at time zone 'Asia/Riyadh')::date + 0 + time '16:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 0 + time '17:30') at time zone 'Asia/Riyadh', 40, null, false, true),
  ('ai-talk', null, 'Tech Talk: Careers in AI', 'حديث تقني: الوظائف في الذكاء الاصطناعي', 'Industry speakers on breaking into ML engineering, data science and AI product roles in the Kingdom.', 'متحدثون من القطاع عن دخول مجالات هندسة تعلم الآلة وعلم البيانات وإدارة منتجات الذكاء الاصطناعي في المملكة.', 'Al-Khudair Hall', 'قاعة الخضير', 'Al-Khudair Hall', 'قاعة الخضير', 'Career Center', 'مركز التوظيف', 'C', ((now() at time zone 'Asia/Riyadh')::date + 7 + time '17:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 7 + time '18:30') at time zone 'Asia/Riyadh', 200, null, false, true),
  ('padel-finals', (select id from public.clubs where slug = 'sports'), 'Padel Tournament Finals', 'نهائي بطولة البادل', 'The top four pairs battle it out for the YU Padel Cup. Come cheer — free drinks for spectators.', 'أفضل أربعة فرق تتنافس على كأس الجامعة للبادل. تعال وشجّع — مشروبات مجانية للحضور.', 'YUPadel', 'YUPadel', 'YUPadel courts', 'ملاعب YUPadel', null, null, 'Y', ((now() at time zone 'Asia/Riyadh')::date + 10 + time '16:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 10 + time '19:00') at time zone 'Asia/Riyadh', 150, null, false, true),
  ('research-day', null, 'Research Day 2026', 'يوم البحث العلمي 2026', 'Student and faculty research posters, three-minute thesis competition, and awards.', 'ملصقات بحثية للطلاب وأعضاء هيئة التدريس، ومسابقة الأطروحة في ثلاث دقائق، وتوزيع الجوائز.', 'Al-Khudair Hall', 'قاعة الخضير', 'Al-Khudair Hall', 'قاعة الخضير', 'Deanship of Research', 'عمادة البحث العلمي', 'D', ((now() at time zone 'Asia/Riyadh')::date + 15 + time '09:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 15 + time '14:00') at time zone 'Asia/Riyadh', 300, null, false, true),
  ('flutter-jam', (select id from public.clubs where slug = 'gdg'), 'Flutter Study Jam', 'ورشة Flutter', 'Build your first Flutter app in two hours. Laptops required; Flutter SDK install guide sent after you RSVP.', 'ابنِ أول تطبيق Flutter في ساعتين. يلزم إحضار لابتوب؛ يُرسل دليل التثبيت بعد التسجيل.', 'Engineering Lab 3', 'معمل الهندسة 3', 'Engineering Lab 3 · College of Engineering', 'معمل الهندسة 3 · كلية الهندسة', null, null, 'G', ((now() at time zone 'Asia/Riyadh')::date + 17 + time '17:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 17 + time '19:00') at time zone 'Asia/Riyadh', 35, null, false, true),
  ('debate-night', (select id from public.clubs where slug = 'debate'), 'Debate Night', 'أمسية المناظرات', 'Motion: "This house would ban homework." Teams of three, British Parliamentary format.', 'المقترح: "يجب إلغاء الواجبات المنزلية". فرق من ثلاثة أعضاء بنظام البرلمان البريطاني.', 'Tuwaiq Building', 'مبنى طويق', 'Tuwaiq Building · Auditorium', 'مبنى طويق · المسرح', null, null, 'D', ((now() at time zone 'Asia/Riyadh')::date + 19 + time '19:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 19 + time '21:00') at time zone 'Asia/Riyadh', 90, null, false, true),
  ('cloud-workshop', (select id from public.clubs where slug = 'gdg'), 'Cloud Workshop', 'ورشة الحوسبة السحابية', 'Hands-on intro to deploying apps on Google Cloud.', 'مقدمة عملية لنشر التطبيقات على Google Cloud.', 'Innovation Hub', 'مركز الابتكار', 'Innovation Hub · Building A, Floor 2', 'مركز الابتكار · مبنى A، الدور 2', null, null, 'G', ((now() at time zone 'Asia/Riyadh')::date + 30 + time '17:00') at time zone 'Asia/Riyadh', ((now() at time zone 'Asia/Riyadh')::date + 30 + time '19:00') at time zone 'Asia/Riyadh', 40, null, true, false);
